import{_ as e,a0 as t,w as o,s as r,ao as c,I as p,x as a,a1 as l,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上使用 kill 和 killall 命令来管理进程 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 kill 和 killall 命令来管理进程 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 kill 和 killall 命令来管理进程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 kill 和 killall 命令来管理进程 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20200127 Managing processes on Linux with kill and killall","title":"在 Linux 上使用 kill 和 killall 命令来管理进程","tag":"202103","desc":""},"relativePath":"202103/20200127 Managing processes on Linux with kill and killall.md","filePath":"[post].md"}'),d={name:"202103/20200127 Managing processes on Linux with kill and killall.md"};function h(u,s,k,g,m,b){const n=t("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-上使用-kill-和-killall-命令来管理进程" tabindex="-1">在 Linux 上使用 kill 和 killall 命令来管理进程 <a class="header-anchor" href="#在-linux-上使用-kill-和-killall-命令来管理进程" aria-label="Permalink to “在 Linux 上使用 kill 和 killall 命令来管理进程”">​</a></h1><blockquote><p>了解如何使用 ps、kill 和 killall 命令来终止进程并回收系统资源。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202103/18/230625q6g65gz6ugdk8ygr.jpg" alt=""></p><p>在 Linux 中，每个程序和<ruby>守护程序<rt>daemon</rt></ruby>都是一个“<ruby>进程<rt>process</rt></ruby>”。 大多数进程代表一个正在运行的程序。而另外一些程序可以派生出其他进程，比如说它会侦听某些事件的发生，然后对其做出响应。并且每个进程都需要一定的内存和处理能力。你运行的进程越多，所需的内存和 CPU 使用周期就越多。在老式电脑（例如我使用了 7 年的笔记本电脑）或轻量级计算机（例如树莓派）上，如果你关注过后台运行的进程，就能充分利用你的系统。</p><p>你可以使用 <code>ps</code> 命令来查看正在运行的进程。你通常会使用 <code>ps</code> 命令的参数来显示出更多的输出信息。我喜欢使用 <code>-e</code> 参数来查看每个正在运行的进程，以及 <code>-f</code> 参数来获得每个进程的全部细节。以下是一些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps</span></span>
<span class="line"><span>    PID TTY          TIME CMD</span></span>
<span class="line"><span>  88000 pts/0    00:00:00 bash</span></span>
<span class="line"><span>  88052 pts/0    00:00:00 ps</span></span>
<span class="line"><span>  88053 pts/0    00:00:00 head</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -e | head</span></span>
<span class="line"><span>    PID TTY          TIME CMD</span></span>
<span class="line"><span>      1 ?        00:00:50 systemd</span></span>
<span class="line"><span>      2 ?        00:00:00 kthreadd</span></span>
<span class="line"><span>      3 ?        00:00:00 rcu_gp</span></span>
<span class="line"><span>      4 ?        00:00:00 rcu_par_gp</span></span>
<span class="line"><span>      6 ?        00:00:02 kworker/0:0H-events_highpri</span></span>
<span class="line"><span>      9 ?        00:00:00 mm_percpu_wq</span></span>
<span class="line"><span>     10 ?        00:00:01 ksoftirqd/0</span></span>
<span class="line"><span>     11 ?        00:00:12 rcu_sched</span></span>
<span class="line"><span>     12 ?        00:00:00 migration/0</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | head</span></span>
<span class="line"><span>UID          PID    PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>root           1       0  0 13:51 ?        00:00:50 /usr/lib/systemd/systemd --switched-root --system --deserialize 36</span></span>
<span class="line"><span>root           2       0  0 13:51 ?        00:00:00 [kthreadd]</span></span>
<span class="line"><span>root           3       2  0 13:51 ?        00:00:00 [rcu_gp]</span></span>
<span class="line"><span>root           4       2  0 13:51 ?        00:00:00 [rcu_par_gp]</span></span>
<span class="line"><span>root           6       2  0 13:51 ?        00:00:02 [kworker/0:0H-kblockd]</span></span>
<span class="line"><span>root           9       2  0 13:51 ?        00:00:00 [mm_percpu_wq]</span></span>
<span class="line"><span>root          10       2  0 13:51 ?        00:00:01 [ksoftirqd/0]</span></span>
<span class="line"><span>root          11       2  0 13:51 ?        00:00:12 [rcu_sched]</span></span>
<span class="line"><span>root          12       2  0 13:51 ?        00:00:00 [migration/0]</span></span></code></pre></div><p>最后的例子显示最多的细节。在每一行，<code>UID</code>（用户 ID）显示了该进程的所有者。<code>PID</code>（进程 ID）代表每个进程的数字 ID，而 <code>PPID</code>（父进程 ID）表示其父进程的数字 ID。在任何 Unix 系统中，进程是从 1 开始编号，是内核启动后运行的第一个进程。在这里，<code>systemd</code> 是第一个进程，它催生了 <code>kthreadd</code>，而 <code>kthreadd</code> 还创建了其他进程，包括 <code>rcu_gp</code>、<code>rcu_par_gp</code> 等一系列进程。</p><h3 id="使用-kill-命令来管理进程" tabindex="-1">使用 kill 命令来管理进程 <a class="header-anchor" href="#使用-kill-命令来管理进程" aria-label="Permalink to “使用 kill 命令来管理进程”">​</a></h3><p>系统会处理大多数后台进程，所以你不需要操心这些进程。你只需要关注那些你所运行的应用创建的进程。虽然许多应用一次只运行一个进程（如音乐播放器、终端模拟器或游戏等），但其他应用则可能创建后台进程。其中一些应用可能当你退出后还在后台运行，以便下次你使用的时候能快速启动。</p><p>当我运行 Chromium（作为谷歌 Chrome 浏览器所基于的开源项目）时，进程管理便成了问题。 Chromium 在我的笔记本电脑上运行非常吃力，并产生了许多额外的进程。现在我仅打开五个选项卡，就能看到这些 Chromium 进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep chromium</span></span>
<span class="line"><span>jhall      66221   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>jhall      66230   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>jhall      66861   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>jhall      67329   65132  0 15:45 pts/0    00:00:00 grep -F chromium</span></span></code></pre></div><p>我已经省略一些行，其中有 20 个 Chromium 进程和一个正在搜索 “chromium&quot; 字符的 <code>grep</code> 进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep chromium | wc -l</span></span>
<span class="line"><span>21</span></span></code></pre></div><p>但是在我退出 Chromium 之后，这些进程仍旧运行。如何关闭它们并回收这些进程占用的内存和 CPU 呢？</p><p><code>kill</code> 命令能让你终止一个进程。在最简单的情况下，你告诉 <code>kill</code> 命令终止你想终止的进程的 PID。例如，要终止这些进程，我需要对 20 个 Chromium 进程 ID 都执行 <code>kill</code> 命令。一种方法是使用命令行获取 Chromium 的 PID，而另一种方法针对该列表运行 <code>kill</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep /usr/lib64/chromium-browser/chromium-browser | awk &#39;{print $2}&#39;</span></span>
<span class="line"><span>66221</span></span>
<span class="line"><span>66230</span></span>
<span class="line"><span>66239</span></span>
<span class="line"><span>66257</span></span>
<span class="line"><span>66262</span></span>
<span class="line"><span>66283</span></span>
<span class="line"><span>66284</span></span>
<span class="line"><span>66285</span></span>
<span class="line"><span>66324</span></span>
<span class="line"><span>66337</span></span>
<span class="line"><span>66360</span></span>
<span class="line"><span>66370</span></span>
<span class="line"><span>66386</span></span>
<span class="line"><span>66402</span></span>
<span class="line"><span>66503</span></span>
<span class="line"><span>66539</span></span>
<span class="line"><span>66595</span></span>
<span class="line"><span>66734</span></span>
<span class="line"><span>66848</span></span>
<span class="line"><span>66861</span></span>
<span class="line"><span>69702</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ps -ef | fgrep /usr/lib64/chromium-browser/chromium-browser | awk &#39;{print $2}&#39; &gt; /tmp/pids</span></span>
<span class="line"><span>$ kill $(cat /tmp/pids)</span></span></code></pre></div><p>最后两行是关键。第一个命令行为 Chromium 浏览器生成一个进程 ID 列表。第二个命令行针对该进程 ID 列表运行 <code>kill</code> 命令。</p><h3 id="介绍-killall-命令" tabindex="-1">介绍 killall 命令 <a class="header-anchor" href="#介绍-killall-命令" aria-label="Permalink to “介绍 killall 命令”">​</a></h3><p>一次终止多个进程有个更简单方法，使用 <code>killall</code> 命令。你或许可以根据名称猜测出，<code>killall</code> 会终止所有与该名字匹配的进程。这意味着我们可以使用此命令来停止所有流氓 Chromium 进程。这很简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ killall /usr/lib64/chromium-browser/chromium-browser</span></span></code></pre></div><p>但是要小心使用 <code>killall</code>。该命令能够终止与你所给出名称相匹配的所有进程。这就是为什么我喜欢先使用 <code>ps -ef</code> 命令来检查我正在运行的进程，然后针对要停止的命令的准确路径运行 <code>killall</code>。</p><p>你也可以使用 <code>-i</code> 或 <code>--interactive</code> 参数，来让 <code>killkill</code> 在停止每个进程之前提示你。</p><p><code>killall</code> 还支持使用 <code>-o</code> 或 <code>--older-than</code> 参数来查找比特定时间更早的进程。例如，如果你发现了一组已经运行了好几天的恶意进程，这将会很有帮助。又或是，你可以查找比特定时间更晚的进程，例如你最近启动的失控进程。使用 <code>-y</code> 或 <code>--young-than</code> 参数来查找这些进程。</p><h3 id="其他管理进程的方式" tabindex="-1">其他管理进程的方式 <a class="header-anchor" href="#其他管理进程的方式" aria-label="Permalink to “其他管理进程的方式”">​</a></h3><p>进程管理是系统维护重要的一部分。在我作为 Unix 和 Linux 系统管理员的早期职业生涯中，杀死非法作业的能力是保持系统正常运行的关键。在如今，你可能不需要亲手在 Linux 上的终止流氓进程，但是知道 <code>kill</code> 和 <code>killall</code> 能够在最终出现问题时为你提供帮助。</p><p>你也能寻找其他方式来管理进程。在我这个案例中，我并不需要在我退出浏览器后，使用 <code>kill</code> 或 <code>killall</code> 来终止后台 Chromium 进程。在 Chromium 中有个简单设置就可以进行控制：</p><p><img src="https://opensource.com/sites/default/files/uploads/chromium-settings-continue-running.png" alt="Chromium background processes setting" title="Chromium background processes setting"></p><p>不过，始终关注系统上正在运行哪些进程，并且在需要的时候进行干预是一个明智之举。</p><hr>`,31)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),l(n,{href:"https://opensource.com/article/20/1/linux-kill-killall"},{default:i(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/20/1/linux-kill-killall",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),l(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),l(n,{href:"https://github.com/wyxplus"},{default:i(()=>[...s[4]||(s[4]=[a("wyxplus",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=e(d,[["render",h]]);export{x as __pageData,y as default};
